input.old_string:
Card(Modifier.weight(1f).fillMaxHeight()) {
    Row(Modifier.fillMaxSize().padding(16.dp)) {
        Box(
            Modifier.fillMaxHeight().aspectRatio(0.85f).clip(RoundedCornerShape(10.dp))
                .background(Brush.verticalGradient(listOf(post.tint.copy(alpha = 0.6f), post.tint)))
        )
        HSpace(16)
        Column(Modifier.fillMaxHeight()) {
            T(post.title, 18.sp, weight = FontWeight.Bold)
            VSpace(4)
            T("@${post.author} · ♥ ${post.likes}", 13.sp, C.Sub)
            VSpace(8)
            T("${post.km}km · 방문 ${post.places}곳", 14.sp, C.Sub)
            Spacer(Modifier.weight(1f))
            Box(
                Modifier.clip(RoundedCornerShape(8.dp)).border(1.dp, C.Green, RoundedCornerShape(8.dp))
                    .clickable { onImport(post) }.padding(horizontal = 14.dp, vertical = 9.dp)
            ) { T("내 코스로 가져오기", 14.sp, C.Green, FontWeight.Medium) }
        }
    }
}

input.new_string:
